INSERT INTO commands(workspace_id,command_id,device_id,stream_key,origin_type,actor_user_id,value_type,boolean_value,admitted_at,deadline_at,manual_epoch_snapshot)
 VALUES(pg_temp.fixture_id(101),pg_temp.fixture_id(501),pg_temp.fixture_id(301),'fan','MANUAL',pg_temp.fixture_id(1),'BOOLEAN',true,now(),now()+interval '10 seconds',0);
SELECT pg_temp.rejects('command_active_actuator_unique', $$INSERT INTO commands(workspace_id,command_id,device_id,stream_key,origin_type,actor_user_id,value_type,boolean_value,admitted_at,deadline_at,manual_epoch_snapshot) VALUES(pg_temp.fixture_id(101),pg_temp.fixture_id(502),pg_temp.fixture_id(301),'fan','MANUAL',pg_temp.fixture_id(1),'BOOLEAN',false,now(),now()+interval '10 seconds',0)$$,'23505','uq_commands_active_actuator');
SELECT pg_temp.rejects('command_cannot_skip_dispatch', $$UPDATE commands SET state='SUCCEEDED',outcome='SUCCEEDED',terminal_at=now()$$,'23514','ck_command_transition');
UPDATE commands SET state='DISPATCHING',dispatch_intent_at=now();
UPDATE commands SET state='TIMED_OUT',outcome='UNKNOWN',terminal_at=now();
SELECT pg_temp.rejects('command_terminal_truth_immutable', $$UPDATE commands SET state='SUCCEEDED',outcome='SUCCEEDED'$$,'23514','ck_command_terminal_immutable');
INSERT INTO command_evidence VALUES(pg_temp.fixture_id(101),pg_temp.fixture_id(601),pg_temp.fixture_id(501),'LATE_RESULT',now(),decode(repeat('01',32),'hex'),'{"state":"SUCCEEDED"}');
SELECT CASE WHEN outcome='UNKNOWN' THEN 'PASS:late_evidence_preserves_unknown' ELSE 'FAIL:late_evidence_preserves_unknown' END FROM commands WHERE command_id=pg_temp.fixture_id(501);
/* ACK resolution cần CAS revision nhưng không được đổi terminal state/outcome. */
UPDATE commands SET revision=revision+1 WHERE command_id=pg_temp.fixture_id(501);
SELECT CASE WHEN revision=2 AND outcome='UNKNOWN' THEN 'PASS:terminal_resolution_can_advance_revision' ELSE 'FAIL:terminal_resolution_can_advance_revision' END FROM commands WHERE command_id=pg_temp.fixture_id(501);
